import type { BankQuestion } from "@/lib/bank";

/** Hydrogen and s-Block Elements (Chemistry (JEE/NEET)): 118 questions. Append new ones at the end with the next id; never reuse or renumber an id. */
const questions: BankQuestion[] = [
  {"id":"chem-s-block-hydrogen-1","question":"Which isotope of hydrogen is radioactive?","options":["Deuterium","Ortho-hydrogen","Tritium","Protium"],"answer":2,"explanation":"Tritium (³H) is a β-emitter with a half-life of about 12.3 years. Protium and deuterium are stable; ortho-hydrogen is a spin isomer, not an isotope.","difficulty":"easy","source":"NEET"},
  {"id":"chem-s-block-hydrogen-2","question":"The colour imparted to a Bunsen flame by sodium salts is:","options":["Apple green","Lilac","Crimson red","Golden yellow"],"answer":3,"explanation":"Na gives golden yellow; K gives lilac, Sr crimson and Ba apple green.","difficulty":"easy","source":"NEET"},
  {"id":"chem-s-block-hydrogen-3","question":"Which alkaline earth metal is present at the centre of the chlorophyll molecule?","options":["Magnesium","Barium","Beryllium","Calcium"],"answer":0,"explanation":"Chlorophyll is a magnesium–porphyrin complex; Ca²⁺ is important in bones, teeth and blood clotting instead.","difficulty":"easy","source":"NEET"},
  {"id":"chem-s-block-hydrogen-4","question":"Which alkali metal is the strongest reducing agent in aqueous solution?","options":["Sodium","Potassium","Lithium","Caesium"],"answer":2,"explanation":"Li has the most negative E° (−3.04 V) because its very high hydration enthalpy outweighs its high ionisation enthalpy, even though Cs has the lowest IE.","difficulty":"moderate","source":"JEE Main · NEET"},
  {"id":"chem-s-block-hydrogen-5","question":"In Clark's method, temporary hardness of water is removed by adding:","options":["Calgon","A calculated amount of lime, Ca(OH)₂","Excess sodium chloride","Washing soda"],"answer":1,"explanation":"Ca(HCO₃)₂ + Ca(OH)₂ → 2CaCO₃↓ + 2H₂O. Excess lime would itself add hardness, so the amount is calculated.","difficulty":"moderate","source":"NEET"},
  {"id":"chem-s-block-hydrogen-6","question":"The molarity of a '10 volume' hydrogen peroxide solution is about:","options":["1.79 M","0.45 M","3.03 M","0.89 M"],"answer":3,"explanation":"2H₂O₂ → 2H₂O + O₂: 1 L of 10-volume H₂O₂ gives 10 L O₂ at STP = 10/22.4 mol O₂, needing 2 × 10/22.4 = 0.893 mol H₂O₂. So M = volume strength/11.2 = 0.89 M.","difficulty":"moderate","source":"JEE Main · NEET"},
  {"id":"chem-s-block-hydrogen-7","question":"Which of the following hydroxides is amphoteric?","options":["Mg(OH)₂","Ba(OH)₂","Be(OH)₂","Ca(OH)₂"],"answer":2,"explanation":"Be(OH)₂ dissolves in acids and in alkalis (giving [Be(OH)₄]²⁻). The other group 2 hydroxides are basic.","difficulty":"moderate","source":"NEET"},
  {"id":"chem-s-block-hydrogen-8","question":"Which of the following sulphates is the least soluble in water?","options":["CaSO₄","BaSO₄","MgSO₄","BeSO₄"],"answer":1,"explanation":"Solubility of group 2 sulphates falls down the group because hydration enthalpy falls faster than lattice enthalpy; BaSO₄ is practically insoluble.","difficulty":"moderate","source":"NEET"},
  {"id":"chem-s-block-hydrogen-9","question":"The Solvay process cannot be used to make potassium carbonate because:","options":["K₂CO₃ decomposes on heating","KCl does not dissolve in water","KHCO₃ is too soluble to be precipitated by passing CO₂ into ammoniated brine","Potassium reacts with ammonia"],"answer":2,"explanation":"The Solvay process depends on NaHCO₃ crystallising out of solution. KHCO₃ is much more soluble, so it does not separate.","difficulty":"moderate","source":"NEET"},
  {"id":"chem-s-block-hydrogen-10","question":"Which statement about a dilute solution of sodium in liquid ammonia is INCORRECT?","options":["It conducts electricity","It is blue because of ammoniated electrons","It is diamagnetic because the ammoniated electrons pair up","It is a strong reducing agent"],"answer":2,"explanation":"Dilute solutions are blue and paramagnetic (unpaired ammoniated electrons). Only concentrated solutions turn bronze and diamagnetic as the electrons pair.","difficulty":"hard","source":"NEET"},
  {"id":"chem-s-block-hydrogen-11","question":"The correct order of thermal stability of the alkaline earth metal carbonates is:","options":["All are equally stable","MgCO₃ < BeCO₃ < CaCO₃ < BaCO₃ < SrCO₃","BeCO₃ < MgCO₃ < CaCO₃ < SrCO₃ < BaCO₃","BaCO₃ < SrCO₃ < CaCO₃ < MgCO₃ < BeCO₃"],"answer":2,"explanation":"Larger cations polarise the carbonate ion less, so stability rises down the group; BeCO₃ is so unstable it is kept under CO₂.","difficulty":"hard","source":"JEE Main · NEET"},
  {"id":"chem-s-block-hydrogen-12","question":"When lithium burns in air, the main products are:","options":["LiH only","Li₂O₂ only","Li₂O together with Li₃N","LiO₂ only"],"answer":2,"explanation":"Li forms the normal oxide Li₂O and, like Mg (diagonal relationship), reacts directly with N₂ to give Li₃N. Na gives mainly Na₂O₂ and K gives KO₂.","difficulty":"hard","source":"NEET"},
  {"id":"chem-s-block-hydrogen-13","question":"Which of the following compounds is paramagnetic?","options":["KO₂","BaO₂","Li₂O","Na₂O₂"],"answer":0,"explanation":"The superoxide ion O₂⁻ has one unpaired electron (bond order 1.5). Peroxide O₂²⁻ and oxide O²⁻ have all electrons paired.","difficulty":"hard","source":"JEE Main · NEET"},
  {"id":"chem-s-block-hydrogen-14","question":"Which statement correctly describes the structure of the H₂O₂ molecule?","options":["It is planar with both H atoms on the same side","It is linear","It is planar with a dihedral angle of 180°","It is non-planar (open book), with a dihedral angle of about 111.5° in the gas phase"],"answer":3,"explanation":"H₂O₂ has a skewed open-book structure: the dihedral angle is 111.5° in the gas phase and about 90.2° in the solid.","difficulty":"hard","source":"NEET"},
  {"id":"chem-s-block-hydrogen-15","question":"The correct order of ionic mobility of the alkali metal ions in water is:","options":["Cs⁺ < Rb⁺ < K⁺ < Na⁺ < Li⁺","All have equal mobility","Li⁺ < Na⁺ < K⁺ < Rb⁺ < Cs⁺","Na⁺ < Li⁺ < K⁺ < Cs⁺ < Rb⁺"],"answer":2,"explanation":"Li⁺ is the smallest bare ion but the most heavily hydrated, so its hydrated radius is the largest and it moves slowest; mobility rises down the group.","difficulty":"hard","source":"NEET"},
  {"id":"chem-s-block-hydrogen-16","question":"Which of the following hydrides is electron-rich?","options":["CaH₂","CH₄","NH₃","B₂H₆"],"answer":2,"explanation":"NH₃ has a lone pair beyond its bonding pairs (electron-rich). B₂H₆ is electron-deficient, CH₄ electron-precise and CaH₂ is an ionic (saline) hydride.","difficulty":"hard","source":"NEET"},
  {"id":"chem-s-block-hydrogen-17","question":"Calgon, used to soften hard water, is:","options":["Sodium carbonate decahydrate","Sodium aluminium silicate","Calcium hydroxide","Sodium hexametaphosphate"],"answer":3,"explanation":"Calgon, Na₆P₆O₁₈ (Na₂[Na₄(PO₃)₆]), forms soluble complexes with Ca²⁺ and Mg²⁺. Sodium aluminium silicate is zeolite (permutit).","difficulty":"hard","source":"JEE Main · NEET"},
  {"id":"chem-s-block-hydrogen-18","question":"In deionisation of water by synthetic resins, after water passes through the cation-exchange resin (in its H⁺ form), the water becomes:","options":["Acidic, because Ca²⁺, Mg²⁺ and Na⁺ are exchanged for H⁺","Completely pure, so no anion exchanger is needed","Hard, because Na⁺ is added","Basic, because OH⁻ ions are released"],"answer":0,"explanation":"2RH + M²⁺ → R₂M + 2H⁺, so the water turns acidic. The anion exchanger (R–OH form) then removes anions, releasing OH⁻ that neutralises the H⁺.","difficulty":"hard","source":"JEE Main · NEET"},
  {"id":"chem-s-block-hydrogen-19","question":"How many of the following statements are correct? (A) At very low temperatures dihydrogen is almost entirely para-hydrogen. (B) Heavy water (D₂O) has a higher boiling point than ordinary water. (C) D₂O is used as a moderator in nuclear reactors. (D) Dihydrogen is conveniently prepared by the action of dilute nitric acid on zinc.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"A, B (374.4 K vs 373 K) and C are correct. D is wrong: HNO₃ is an oxidising acid and gives oxides of nitrogen, not H₂.","difficulty":"very-hard","source":"JEE Main · NEET"},
  {"id":"chem-s-block-hydrogen-20","question":"Assertion (A): Lithium is the strongest reducing agent among the alkali metals in aqueous solution, although it has the highest ionisation enthalpy. Reason (R): The very large hydration enthalpy of Li⁺ more than compensates for its high ionisation and sublimation enthalpies.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"Both are true. E° depends on sublimation + ionisation − hydration energies; the huge hydration enthalpy of the small Li⁺ ion makes E°(Li⁺/Li) the most negative.","difficulty":"very-hard","source":"NEET · JEE Main"},
  {"id":"chem-s-block-hydrogen-21","question":"Match the compound (Column I) with its use (Column II). (a) Quicklime, (b) Plaster of Paris, (c) Washing soda, (d) Baking soda. (1) Antacid and fire extinguishers; (2) Plaster casts for fractured bones; (3) Manufacture of cement; (4) Removal of permanent hardness of water.","options":["a-3, b-2, c-1, d-4","a-2, b-3, c-1, d-4","a-3, b-2, c-4, d-1","a-4, b-2, c-3, d-1"],"answer":2,"explanation":"CaO is a raw material for cement; PoP sets into casts; Na₂CO₃·10H₂O precipitates Ca²⁺/Mg²⁺ as carbonates (permanent hardness); NaHCO₃ is an antacid and a CO₂ source in extinguishers.","difficulty":"very-hard","source":"NEET"},
  {"id":"chem-s-block-hydrogen-22","question":"A 1 L sample of water contains 81 mg of Ca(HCO₃)₂ and 73 mg of Mg(HCO₃)₂. Its hardness expressed as ppm of CaCO₃ is (Ca = 40, Mg = 24):","options":["100 ppm","50 ppm","154 ppm","200 ppm"],"answer":0,"explanation":"Ca(HCO₃)₂ (162): 81/162 = 0.5 mmol; Mg(HCO₃)₂ (146): 73/146 = 0.5 mmol. Total 1 mmol ≡ 1 mmol CaCO₃ = 100 mg per litre = 100 ppm. 154 ppm just adds the masses.","difficulty":"very-hard","source":"JEE Main"},
  {"id":"chem-s-block-hydrogen-23","question":"20 mL of an H₂O₂ solution needs 40 mL of 0.02 M KMnO₄ for complete reaction in acidic medium. The volume strength of the H₂O₂ solution is:","options":["0.56 volume","11.2 volume","1.12 volume","2.24 volume"],"answer":2,"explanation":"2MnO₄⁻ + 5H₂O₂ + 6H⁺ → 2Mn²⁺ + 5O₂ + 8H₂O. n(KMnO₄) = 8 × 10⁻⁴, n(H₂O₂) = 2 × 10⁻³ mol in 20 mL → 0.1 M. Volume strength = 11.2 × M = 1.12.","difficulty":"very-hard","source":"JEE Main"},
  {"id":"chem-s-block-hydrogen-24","question":"Which of the following does NOT increase on going down group 1 from Li to Cs?","options":["Electropositive character","Melting point","Reactivity towards water","Atomic radius"],"answer":1,"explanation":"Metallic bonding weakens as atoms grow larger, so melting point falls (Li 454 K to Cs 302 K). Size, reactivity and electropositivity all increase.","difficulty":"very-hard","source":"JEE Main · NEET"},
  {"id":"chem-s-block-hydrogen-25","question":"Which pair of solubility orders for group 2 compounds is correct?","options":["Hydroxides: Be(OH)₂ > Mg(OH)₂ > Ca(OH)₂ > Ba(OH)₂; sulphates: BeSO₄ > MgSO₄ > CaSO₄ > BaSO₄","Hydroxides: Be(OH)₂ < Mg(OH)₂ < Ca(OH)₂ < Ba(OH)₂; sulphates: BeSO₄ > MgSO₄ > CaSO₄ > BaSO₄","Hydroxides: Be(OH)₂ > Mg(OH)₂ > Ca(OH)₂ > Ba(OH)₂; sulphates: BeSO₄ < MgSO₄ < CaSO₄ < BaSO₄","Hydroxides: Be(OH)₂ < Mg(OH)₂ < Ca(OH)₂ < Ba(OH)₂; sulphates: BeSO₄ < MgSO₄ < CaSO₄ < BaSO₄"],"answer":1,"explanation":"The two trends run opposite. For the small OH⁻ ion, lattice enthalpy falls faster than hydration enthalpy down the group (solubility rises); for the large SO₄²⁻ ion lattice enthalpy hardly changes, so falling hydration enthalpy lowers solubility.","difficulty":"very-hard","source":"NEET · JEE Main"},
  {"id":"chem-s-block-hydrogen-26","question":"Potassium superoxide in breathing apparatus absorbs CO₂: 4KO₂ + 2CO₂ → 2K₂CO₃ + 3O₂. The volume of O₂ at STP released per mole of CO₂ absorbed is:","options":["22.4 L","33.6 L","44.8 L","11.2 L"],"answer":1,"explanation":"2 mol CO₂ give 3 mol O₂, so 1 mol CO₂ gives 1.5 mol O₂ = 1.5 × 22.4 = 33.6 L at STP.","difficulty":"very-hard","source":"JEE Main · NEET"},
  {"id":"chem-s-block-hydrogen-27","question":"How many of the following statements are correct? (A) Beryllium and magnesium do not impart colour to the flame. (B) BeO is amphoteric. (C) Be₂C on hydrolysis gives ethyne. (D) The basic strength of the hydroxides of Ca, Sr and Ba decreases down the group.","options":["Only one","Only two","Only three","All four"],"answer":1,"explanation":"A (their electrons are too tightly bound for visible excitation) and B are correct. C is wrong: Be₂C gives methane. D is wrong: basic strength increases down the group.","difficulty":"very-hard","source":"JEE Main · NEET"},
  {"id":"chem-s-block-hydrogen-28","question":"Which carbide gives propyne on hydrolysis?","options":["Al₄C₃","Be₂C","CaC₂","Mg₂C₃"],"answer":3,"explanation":"Mg₂C₃ contains C₃⁴⁻ and gives CH₃–C≡CH. CaC₂ (C₂²⁻) gives ethyne; Be₂C and Al₄C₃ (C⁴⁻) give methane.","difficulty":"very-hard","source":"JEE Main · NEET"},
  {"id":"chem-s-block-hydrogen-29","question":"Which statement about the Solvay (ammonia–soda) process is INCORRECT?","options":["Ammonia is recovered by heating NH₄Cl with Ca(OH)₂","NaHCO₃ precipitates because of its low solubility","CO₂ is passed through brine saturated with ammonia","Its only by-product is NH₄Cl, which is sold as a fertiliser"],"answer":3,"explanation":"NH₄Cl is not a by-product: it is treated with Ca(OH)₂ to recover NH₃ for reuse, leaving CaCl₂ as the by-product.","difficulty":"very-hard","source":"NEET"},
  {"id":"chem-s-block-hydrogen-30","question":"Plaster of Paris sets according to 2CaSO₄·½H₂O + 3H₂O → 2CaSO₄·2H₂O. The mass of water needed to set 290 g of Plaster of Paris (molar mass 145 g/mol) is:","options":["18 g","54 g","36 g","27 g"],"answer":1,"explanation":"290 g = 2 mol CaSO₄·½H₂O, which takes up 3 mol H₂O = 54 g. 27 g would wrongly use 1.5 mol water per 2 mol.","difficulty":"very-hard","source":"JEE Main · NEET"},
  {"id": "chem-s-block-hydrogen-31", "question": "Which alkali metal, because of its very low ionisation enthalpy, is used in photoelectric cells?", "options": ["Sodium", "Lithium", "Caesium", "Potassium"], "answer": 2, "explanation": "Caesium has the lowest ionisation enthalpy of the stable alkali metals, so light easily ejects electrons from its surface. Potassium is also photosensitive, but caesium is the standard choice.", "difficulty": "easy", "source": "NEET pattern"},
  {"id": "chem-s-block-hydrogen-32", "question": "The chemical formula of gypsum is:", "options": ["CaCO₃·MgCO₃", "CaSO₄·2H₂O", "CaSO₄", "CaSO₄·½H₂O"], "answer": 1, "explanation": "Gypsum is calcium sulphate dihydrate, CaSO₄·2H₂O. CaSO₄·½H₂O is Plaster of Paris and CaCO₃·MgCO₃ is dolomite.", "difficulty": "easy", "source": "JEE Main · NEET"},
  {"id": "chem-s-block-hydrogen-33", "question": "Which of the following is an ionic (saline) hydride?", "options": ["NH₃", "B₂H₆", "CH₄", "NaH"], "answer": 3, "explanation": "The s-block metals (except Be, Mg) form ionic hydrides containing H⁻, such as NaH. B₂H₆, CH₄ and NH₃ are covalent (molecular) hydrides.", "difficulty": "easy", "source": "JEE Main · NEET"},
  {"id": "chem-s-block-hydrogen-34", "question": "In the permutit (zeolite) method of softening water:", "options": ["Ca²⁺ is complexed by sodium hexametaphosphate", "Ca²⁺ and Mg²⁺ are exchanged for Na⁺ of sodium aluminium silicate", "Ca²⁺ and Mg²⁺ are exchanged for H⁺ of an organic resin", "Hardness ions are precipitated as carbonates by Na₂CO₃"], "answer": 1, "explanation": "Zeolite (NaAlSiO₄) takes up Ca²⁺/Mg²⁺ and releases Na⁺; the exhausted zeolite is regenerated with brine. H⁺-exchange is the synthetic resin method, and hexametaphosphate is Calgon.", "difficulty": "moderate", "source": "JEE Main · NEET"},
  {"id": "chem-s-block-hydrogen-35", "question": "Industrially, hydrogen peroxide is now manufactured mainly by:", "options": ["Action of water on sodium peroxide", "Action of dilute H₂SO₄ on BaO₂", "Electrolysis of 50% H₂SO₄", "Auto-oxidation of 2-ethylanthraquinol"], "answer": 3, "explanation": "2-Ethylanthraquinol is oxidised by air to 2-ethylanthraquinone and H₂O₂; the quinone is then reduced back with H₂ and reused. BaO₂ + H₂SO₄ is a laboratory method.", "difficulty": "moderate", "source": "JEE Main · NEET"},
  {"id": "chem-s-block-hydrogen-36", "question": "Which alkali metal carbonate decomposes on heating to give its oxide and CO₂?", "options": ["K₂CO₃", "Na₂CO₃", "Li₂CO₃", "Cs₂CO₃"], "answer": 2, "explanation": "The small, highly polarising Li⁺ destabilises the large CO₃²⁻ ion, so Li₂CO₃ → Li₂O + CO₂ on heating (like MgCO₃, a diagonal relationship). The other alkali metal carbonates are stable to heat.", "difficulty": "moderate", "source": "JEE Main · NEET"},
  {"id": "chem-s-block-hydrogen-37", "question": "Which of the following hydrides is typically non-stoichiometric?", "options": ["NaH", "TiH₁.₇", "CH₄", "CaH₂"], "answer": 1, "explanation": "d- and f-block metals form interstitial (metallic) hydrides whose composition varies, e.g. TiH₁.₅–₁.₈ or LaH₂.₈₇. Ionic hydrides (NaH, CaH₂) and covalent hydrides (CH₄) have fixed compositions.", "difficulty": "moderate", "source": "NEET pattern"},
  {"id": "chem-s-block-hydrogen-38", "question": "In the Castner–Kellner cell for making NaOH, sodium is discharged at the cathode as:", "options": ["Sodium amalgam at a mercury cathode", "Molten sodium at an iron cathode", "Na⁺ that stays in solution", "Sodium hydride"], "answer": 0, "explanation": "Brine is electrolysed with a mercury cathode and carbon anode; Na forms an amalgam with Hg instead of H₂ being evolved. The amalgam is then treated with water to give NaOH and H₂.", "difficulty": "moderate", "source": "JEE Main · NEET"},
  {"id": "chem-s-block-hydrogen-39", "question": "Which alkaline earth metal does not react with water even at high temperature?", "options": ["Magnesium", "Beryllium", "Barium", "Calcium"], "answer": 1, "explanation": "Beryllium is protected by a thin oxide film and has a high ionisation enthalpy, so it does not react with water or steam even when red hot. Mg reacts with hot water; Ca and Ba react with cold water.", "difficulty": "moderate", "source": "JEE Main · NEET"},
  {"id": "chem-s-block-hydrogen-40", "question": "In which property does hydrogen resemble the halogens rather than the alkali metals?", "options": ["It reacts with oxygen to form an oxide", "It gains one electron to form a uninegative ion (H⁻)", "It forms a unipositive ion in many of its compounds", "It has a single electron in its valence shell"], "answer": 1, "explanation": "Like halogens, hydrogen is one electron short of a noble-gas configuration and forms H⁻ in ionic hydrides (and exists as a diatomic molecule). One valence electron and forming a +1 ion are alkali-metal-like properties.", "difficulty": "hard", "source": "JEE Main · NEET"},
  {"id": "chem-s-block-hydrogen-41", "question": "In which reaction does H₂O₂ act as a reducing agent?", "options": ["Ag₂O + H₂O₂ → 2Ag + H₂O + O₂", "2I⁻ + 2H⁺ + H₂O₂ → I₂ + 2H₂O", "PbS + 4H₂O₂ → PbSO₄ + 4H₂O", "2Fe²⁺ + 2H⁺ + H₂O₂ → 2Fe³⁺ + 2H₂O"], "answer": 0, "explanation": "In Ag₂O + H₂O₂, silver goes from +1 to 0 and the peroxide oxygen goes from −1 to 0 (O₂), so H₂O₂ is oxidised and acts as a reductant. In the other three it oxidises S²⁻, Fe²⁺ and I⁻.", "difficulty": "hard", "source": "JEE Main · NEET"},
  {"id": "chem-s-block-hydrogen-42", "question": "Which nitrate gives brown NO₂ gas on heating?", "options": ["KNO₃", "NaNO₃", "LiNO₃", "RbNO₃"], "answer": 2, "explanation": "4LiNO₃ → 2Li₂O + 4NO₂ + O₂, like Mg(NO₃)₂ (diagonal relationship). The other alkali metal nitrates give the nitrite and O₂ only, e.g. 2NaNO₃ → 2NaNO₂ + O₂.", "difficulty": "hard", "source": "JEE Main · NEET"},
  {"id": "chem-s-block-hydrogen-43", "question": "Which alkali metal halide is the least soluble in water?", "options": ["LiCl", "KF", "NaCl", "LiF"], "answer": 3, "explanation": "LiF has a very high lattice enthalpy (small Li⁺ and small F⁻), which its hydration enthalpy cannot overcome, so it is only sparingly soluble. LiCl is very soluble and even deliquescent.", "difficulty": "hard", "source": "JEE Main · NEET"},
  {"id": "chem-s-block-hydrogen-44", "question": "A burning magnesium ribbon continues to burn when plunged into a jar of CO₂ because:", "options": ["CO₂ decomposes on its own into C and O₂ at room temperature", "Mg reacts with CO₂ to form MgCO₃ with absorption of heat", "Mg has a very high affinity for oxygen and reduces CO₂ to carbon", "CO₂ is a supporter of combustion for all metals"], "answer": 2, "explanation": "2Mg + CO₂ → 2MgO + C is strongly exothermic because Mg takes oxygen from CO₂; black specks of carbon are seen. CO₂ does not support the burning of most substances.", "difficulty": "hard", "source": "JEE Main · NEET"},
  {"id": "chem-s-block-hydrogen-45", "question": "A small amount of gypsum is added to Portland cement clinker in order to:", "options": ["Slow down the setting of cement", "Make the cement waterproof", "Increase its iron content", "Speed up the setting of cement"], "answer": 0, "explanation": "Gypsum (2–3%) is added to the clinker to retard setting so the cement gets sufficiently hardened over time. The main setting compounds are calcium silicates and aluminate.", "difficulty": "hard", "source": "NEET pattern"},
  {"id": "chem-s-block-hydrogen-46", "question": "Which statement about beryllium chloride is correct?", "options": ["It has a chain (polymeric) structure with chloride bridges in the solid state", "It is ionic in the solid state", "It is a linear monomer at all temperatures", "It exists only as a dimer in the solid state"], "answer": 0, "explanation": "Solid BeCl₂ has a chain structure in which each Be is bonded to four bridging Cl atoms. In the vapour it is a chloro-bridged dimer, which breaks into linear monomers at about 1200 K.", "difficulty": "hard", "source": "JEE Main · NEET"},
  {"id": "chem-s-block-hydrogen-47", "question": "In ice, each oxygen atom is:", "options": ["Surrounded octahedrally by six other oxygen atoms", "Surrounded tetrahedrally by four other oxygen atoms at about 276 pm", "Surrounded by twelve oxygen atoms in a close-packed structure", "Hydrogen-bonded to only two other water molecules in a chain"], "answer": 1, "explanation": "Ice has a highly ordered three-dimensional hydrogen-bonded network with each O tetrahedrally surrounded by four O atoms at 276 pm. This open, cage-like structure makes ice less dense than liquid water.", "difficulty": "hard", "source": "JEE Main · NEET"},
  {"id": "chem-s-block-hydrogen-48", "question": "28.6 g of washing soda (Na₂CO₃·10H₂O, molar mass 286 g/mol) is heated above 373 K until its mass is constant. The mass of the residue is:", "options": ["18.0 g", "5.3 g", "10.6 g", "12.4 g"], "answer": 2, "explanation": "Above 373 K the monohydrate loses its last water, leaving anhydrous soda ash. 28.6 g = 0.1 mol, giving 0.1 × 106 = 10.6 g Na₂CO₃. 12.4 g would be the monohydrate, formed only on gentle heating.", "difficulty": "hard", "source": "JEE Main · NEET"},
  {"id": "chem-s-block-hydrogen-49", "question": "Which pair of reactions of sodium peroxide is correct?", "options": ["With cold water: NaOH and H₂; with CO₂: Na₂CO₃ and CO", "With cold water: NaOH and H₂O₂; with CO₂: Na₂CO₃ and O₂", "With cold water: Na₂O and O₂; with CO₂: NaHCO₃", "With cold water: NaOH and O₂ only; with CO₂: Na₂C₂O₄"], "answer": 1, "explanation": "Na₂O₂ + 2H₂O (ice-cold) → 2NaOH + H₂O₂, since O₂²⁻ is the conjugate base of H₂O₂; at higher temperature the H₂O₂ decomposes to give O₂. 2Na₂O₂ + 2CO₂ → 2Na₂CO₃ + O₂ is why it is used to purify air in submarines.", "difficulty": "very-hard", "source": "JEE Main · NEET"},
  {"id": "chem-s-block-hydrogen-50", "question": "How many of the following statements about hydrogen peroxide are correct? (A) It is stored in wax-lined glass or plastic bottles in the dark. (B) A small amount of urea is added to it as a stabiliser. (C) Pure H₂O₂ is an almost colourless (very pale blue) liquid. (D) Because it is less hydrogen-bonded than water, its boiling point is lower than that of water.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "A, B and C are correct: light, dust and rough surfaces catalyse its decomposition. D is wrong: H₂O₂ is more extensively hydrogen-bonded and boils at about 423 K, well above water.", "difficulty": "very-hard", "source": "NEET pattern"},
  {"id": "chem-s-block-hydrogen-51", "question": "Assertion (A): Sodium is stored under kerosene. Reason (R): Sodium reacts with kerosene to form a protective surface layer.", "options": ["Both A and R are true, and R explains A", "Both A and R are true, but R does not explain A", "A is true but R is false", "A is false but R is true"], "answer": 2, "explanation": "A is true: sodium reacts vigorously with oxygen and moisture of air. R is false: sodium does not react with kerosene; the liquid simply keeps air and moisture away from the metal.", "difficulty": "very-hard", "source": "JEE Main · NEET"},
  {"id": "chem-s-block-hydrogen-52", "question": "Match the process (Column I) with its description (Column II). (a) Coal gasification, (b) Water-gas shift reaction, (c) Highest-purity dihydrogen, (d) Dihydrogen as a by-product. (1) Electrolysis of warm Ba(OH)₂ solution with nickel electrodes, (2) CO + H₂O → CO₂ + H₂ over iron chromate, (3) Electrolysis of brine to make NaOH and Cl₂, (4) C + H₂O → CO + H₂ at about 1270 K.", "options": ["a-1, b-2, c-4, d-3", "a-2, b-4, c-1, d-3", "a-4, b-2, c-3, d-1", "a-4, b-2, c-1, d-3"], "answer": 3, "explanation": "Coal gasification makes syngas from carbon and steam (4); the shift reaction converts CO to more H₂ (2). Electrolysis of warm Ba(OH)₂ between Ni electrodes gives H₂ of over 99.5% purity (1), and the chlor-alkali process gives H₂ as a by-product (3).", "difficulty": "very-hard", "source": "NEET pattern"},
  {"id": "chem-s-block-hydrogen-53", "question": "A 6.2 g mixture of sodium and potassium reacts completely with water, giving 2.24 L of H₂ at STP. The mass of sodium in the mixture is (Na = 23, K = 39):", "options": ["3.9 g", "4.6 g", "1.2 g", "2.3 g"], "answer": 3, "explanation": "2M + 2H₂O → 2MOH + H₂, so total metal = 2 × 0.1 = 0.2 mol. x/23 + (6.2 − x)/39 = 0.2 gives 16x = 36.8, x = 2.3 g Na (and 3.9 g K, which is the trap).", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id": "chem-s-block-hydrogen-54", "question": "1.84 g of a mixture of CaCO₃ and MgCO₃ is heated strongly to constant mass, leaving 0.96 g of residue. The mass of CaCO₃ in the mixture is (Ca = 40, Mg = 24):", "options": ["0.50 g", "1.00 g", "1.34 g", "0.84 g"], "answer": 1, "explanation": "CO₂ lost = 0.88 g = 0.02 mol = moles of carbonate. x/100 + (1.84 − x)/84 = 0.02 gives 184 − 16x = 168, x = 1.00 g CaCO₃ (MgCO₃ = 0.84 g). Check: CaO 0.56 g + MgO 0.40 g = 0.96 g.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id": "chem-s-block-hydrogen-55", "question": "How many of the following statements about lithium are correct? (A) Of the alkali metals, only lithium forms a nitride directly. (B) LiCl is soluble in ethanol, showing its partly covalent character. (C) Lithium hydrogencarbonate is obtained as a stable solid. (D) Li₂CO₃ is as stable to heat as Na₂CO₃.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 1, "explanation": "A and B are correct. C is wrong: LiHCO₃ is not obtained in the solid form. D is wrong: Li₂CO₃ decomposes to Li₂O and CO₂ on heating, unlike Na₂CO₃.", "difficulty": "very-hard", "source": "JEE Main · NEET"},
  {"id": "chem-s-block-hydrogen-56", "question": "Assertion (A): BeF₂ is very soluble in water, whereas the fluorides of the other alkaline earth metals are almost insoluble. Reason (R): The hydration enthalpy of the very small Be²⁺ ion is large enough to outweigh the lattice enthalpy of BeF₂.", "options": ["Both A and R are true, and R explains A", "Both A and R are true, but R does not explain A", "A is true but R is false", "A is false but R is true"], "answer": 0, "explanation": "Both are true and R is the reason: solubility depends on hydration enthalpy versus lattice enthalpy, and Be²⁺ has an exceptionally high hydration enthalpy. For CaF₂ to BaF₂ the lattice enthalpy wins, so they are sparingly soluble.", "difficulty": "very-hard", "source": "JEE Advanced pattern"},
  {"id": "chem-s-block-hydrogen-57", "question": "A water sample has temporary hardness due only to Ca(HCO₃)₂, at 162 ppm. The mass of slaked lime needed to soften 1000 L of it by Clark's method is (Ca = 40):", "options": ["37 g", "162 g", "74 g", "148 g"], "answer": 2, "explanation": "162 ppm in 1000 L (1000 kg) is 162 g Ca(HCO₃)₂ = 1 mol (molar mass 162). Ca(HCO₃)₂ + Ca(OH)₂ → 2CaCO₃ + 2H₂O needs 1 mol Ca(OH)₂ = 74 g.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id": "chem-s-block-hydrogen-58", "question": "The correct order of density of the alkali metals is:", "options": ["K < Li < Na < Rb < Cs", "Li < Na < K < Rb < Cs", "Li < K < Na < Rb < Cs", "Cs < Rb < K < Na < Li"], "answer": 2, "explanation": "Density generally rises down the group, but potassium (0.86 g/cm³) is lighter than sodium (0.97 g/cm³) because of its much larger atomic size. Li (0.53) is the lightest; Cs (1.90) the densest.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id": "chem-s-block-hydrogen-59", "question": "How many of the following statements about the biological roles of s-block ions are correct? (A) Mg²⁺ is a cofactor for all enzymes that use ATP in phosphate transfer. (B) Ca²⁺ is needed for blood clotting and muscle contraction. (C) K⁺ is the main cation inside animal cells. (D) About 99% of the calcium in the human body is in bones and teeth.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 3, "explanation": "All four are correct (NCERT). Na⁺ is the main cation outside cells and K⁺ inside; the Na⁺–K⁺ pump maintains these gradients.", "difficulty": "very-hard", "source": "NEET pattern"},
  {"id": "chem-s-block-hydrogen-60", "question": "Which of the following oxides gives hydrogen peroxide when treated with cold dilute H₂SO₄?", "options": ["PbO₂", "NO₂", "MnO₂", "BaO₂"], "answer": 3, "explanation": "Only BaO₂ is a true peroxide containing O₂²⁻: BaO₂·8H₂O + H₂SO₄ → BaSO₄ + H₂O₂ + 8H₂O. PbO₂ and MnO₂ are dioxides with O²⁻ ions (they give O₂, not H₂O₂), and NO₂ is a covalent dioxide.", "difficulty": "very-hard", "source": "JEE Main · NEET"},
  {"id": "chem-s-block-hydrogen-61", "question": "Calcium carbide is treated with heavy water, D₂O. The gaseous product is:", "options": ["C₂D₂", "CD₄", "C₂D₄", "C₃D₄"], "answer": 0, "explanation": "CaC₂ contains the acetylide ion C₂²⁻, which takes two D⁺ from D₂O: CaC₂ + 2D₂O → C₂D₂ + Ca(OD)₂. Methane-type products (CD₄) come from methanides such as Al₄C₃ or Be₂C, and C₃D₄ from Mg₂C₃.", "difficulty": "moderate", "source": "JEE Main"},
  {"id": "chem-s-block-hydrogen-62", "question": "When water containing Mg(HCO₃)₂ is boiled, the magnesium is removed mainly as:", "options": ["MgCO₃", "Mg(OH)₂", "MgO", "MgSO₄"], "answer": 1, "explanation": "Mg(HCO₃)₂ → Mg(OH)₂ + 2CO₂ on boiling. MgCO₃ is fairly soluble (higher solubility product), so it hydrolyses further and the far less soluble Mg(OH)₂ precipitates; calcium, in contrast, comes down as CaCO₃.", "difficulty": "moderate", "source": "JEE Main"},
  {"id": "chem-s-block-hydrogen-63", "question": "In the Downs process for sodium, CaCl₂ is mixed with the NaCl electrolyte mainly in order to:", "options": ["Supply calcium, which is the main product", "Increase the conductivity by forming Ca²⁺ that is discharged first", "Lower the melting point of the electrolyte, so the cell runs at about 873 K instead of above 1080 K", "Prevent chlorine from forming at the anode"], "answer": 2, "explanation": "Pure NaCl melts at about 1081 K; the NaCl–CaCl₂ mixture melts much lower, which saves energy and reduces the volatility of sodium. Na⁺ is discharged at the cathode and Cl₂ at the anode; calcium is not the intended product.", "difficulty": "moderate", "source": "JEE Main"},
  {"id":"chem-s-block-hydrogen-64","question":"Old lead paintings blackened by PbS are restored with H₂O₂. The number of moles of H₂O₂ needed per mole of PbS is:","options":["1","2","8","4"],"answer":3,"explanation":"PbS + 4H₂O₂ → PbSO₄ (white) + 4H₂O. Sulphur goes from −2 to +6 (8 electrons), and each H₂O₂ accepts 2 electrons, so 8/2 = 4 mol. Writing H₂O₂ as a 1-electron oxidant gives 8.","difficulty":"hard","source":"JEE Main"},
  {"id":"chem-s-block-hydrogen-65","question":"The correct order of thermal stability of the alkali metal hydrides is:","options":["LiH > NaH > KH > RbH > CsH","NaH > LiH > KH > RbH > CsH","All are equally stable","CsH > RbH > KH > NaH > LiH"],"answer":0,"explanation":"The lattice energy falls as the cation becomes larger (H⁻ is small, so it fits best with small Li⁺), so stability falls from LiH to CsH. LiH is stable enough to melt without decomposing, which is unusual among saline hydrides.","difficulty":"hard","source":"JEE Main"},
  {"id":"chem-s-block-hydrogen-66","question":"Lithium aluminium hydride is prepared by the reaction:","options":["LiCl + AlH₃ in water","4LiH + AlCl₃ → LiAlH₄ + 3LiCl in dry ether","Li + Al + 2H₂ in aqueous solution","Li₂O + AlCl₃ + H₂ at high temperature"],"answer":1,"explanation":"LiH and AlCl₃ react in dry ether; the LiCl precipitates and LiAlH₄ stays in solution. Water must be excluded entirely, because LiAlH₄ reacts violently with water to give H₂.","difficulty":"hard","source":"JEE Main"},
  {"id": "chem-s-block-hydrogen-67", "question": "Calcium cyanamide, used as a nitrogenous fertiliser, releases ammonia in moist soil. The correct equations for its formation and hydrolysis are:", "options": ["CaO + N₂ → CaCN₂; CaCN₂ + 2H₂O → Ca(OH)₂ + N₂H₄", "CaC₂ + N₂ → CaCN₂ + C (about 1373 K); CaCN₂ + 3H₂O → CaCO₃ + 2NH₃", "CaC₂ + 2NH₃ → CaCN₂ + 3H₂; CaCN₂ + H₂O → CaO + 2HCN", "CaCO₃ + N₂ → CaCN₂ + O₂; CaCN₂ + 3H₂O → Ca(OH)₂ + 2NH₃ + CO"], "answer": 1, "explanation": "Calcium carbide absorbs N₂ at high temperature to give nitrolim (CaCN₂ + C). In soil CaCN₂ is hydrolysed slowly, giving CaCO₃ and two molecules of NH₃, which is why it acts as a slow-release fertiliser.", "difficulty": "hard", "source": "JEE Main"},
  {"id": "chem-s-block-hydrogen-68", "question": "Gypsum heated above 393 K gives 'dead burnt plaster'. It does not set with water because:", "options": ["It is CaSO₄·½H₂O with a large crystal size", "It is CaO formed by decomposition of CaSO₄", "It is anhydrous CaSO₄, which has lost all its water and does not rehydrate readily", "It is CaSO₄·2H₂O, which is already fully hydrated"], "answer": 2, "explanation": "Plaster of Paris (CaSO₄·½H₂O) forms near 393 K; heating beyond that removes all water and gives anhydrous CaSO₄, which has lost the ability to take up water and set. CaSO₄ itself decomposes to CaO only at much higher temperature.", "difficulty": "hard", "source": "JEE Main"},
  {"id": "chem-s-block-hydrogen-69", "question": "Hydrogen peroxide is concentrated by distillation under reduced pressure because:", "options": ["It forms an azeotrope with water at atmospheric pressure", "It is more volatile than water and would be lost", "Reduced pressure converts it into a more stable dimer", "It decomposes (explosively at high concentration) near its normal boiling point, so it must be distilled at a lower temperature"], "answer": 3, "explanation": "The normal boiling point of H₂O₂ is about 423 K, but it decomposes to H₂O and O₂ well below that, violently when concentrated. Lowering the pressure lowers the boiling temperature so water can be removed without decomposition. H₂O₂ is less volatile than water, not more.", "difficulty": "hard", "source": "JEE Main"},
  {"id": "chem-s-block-hydrogen-70", "question": "The correct order of boiling points of these hydrides is:", "options": ["H₂O > HF > NH₃ > CH₄", "HF > H₂O > NH₃ > CH₄", "NH₃ > H₂O > HF > CH₄", "H₂O > NH₃ > HF > CH₄"], "answer": 0, "explanation": "Boiling points: H₂O 373 K, HF 293 K, NH₃ 240 K, CH₄ 112 K. Although an individual H–F···H hydrogen bond is stronger, each water molecule forms on average four hydrogen bonds (two donors, two lone pairs) while HF forms only two, so water boils higher.", "difficulty": "hard", "source": "JEE Main"},
  {"id": "chem-s-block-hydrogen-71", "question": "100 mL of a water sample needs 15.0 mL of 0.010 M EDTA (Eriochrome Black T indicator). After boiling and filtering, 100 mL of the same water needs 6.0 mL of the EDTA. The temporary and permanent hardness, as ppm CaCO₃, are respectively:", "options": ["60 and 90 ppm", "90 and 60 ppm", "150 and 60 ppm", "9 and 6 ppm"], "answer": 1, "explanation": "Total: 15.0 × 0.010 = 0.150 mmol M²⁺ in 100 mL = 1.50 mmol/L = 150 mg CaCO₃/L = 150 ppm. Permanent (after boiling): 6.0 mL → 60 ppm. Temporary = 150 − 60 = 90 ppm. Reporting 150 as the temporary hardness forgets to subtract the part that survives boiling.", "difficulty": "very-hard", "source": "JEE Main"},
  {"id":"chem-s-block-hydrogen-72","question":"10.0 g of a mixture of Na₂CO₃ and NaHCO₃ loses 0.62 g in mass when heated to constant mass. The percentage of NaHCO₃ in the mixture is:","options":["8.4%","6.2%","16.8%","33.6%"],"answer":2,"explanation":"2NaHCO₃ → Na₂CO₃ + H₂O + CO₂: 2 × 84 = 168 g of NaHCO₃ loses 18 + 44 = 62 g. So 0.62 g loss comes from 1.68 g NaHCO₃ = 16.8%. Using 84 g per 62 g (forgetting the factor 2) gives 8.4%; Na₂CO₃ itself does not decompose at these temperatures.","difficulty":"very-hard","source":"JEE Main"},
  {"id": "chem-s-block-hydrogen-73", "question": "How many of the following statements about heavy water are correct? (A) D₂O freezes at a higher temperature (about 276.8 K) than H₂O. (B) The ionic product of D₂O is larger than that of H₂O at the same temperature. (C) On prolonged electrolysis of water, the residual liquid becomes richer in D₂O. (D) Al₄C₃ reacts with D₂O to give CD₄.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "A, C and D are correct; H₂ is liberated faster than D₂ (kinetic isotope effect), so D₂O accumulates in the residue. B is wrong: D₂O ionises less than H₂O (Kw ≈ 1.4 × 10⁻¹⁵ versus 1.0 × 10⁻¹⁴ at 298 K), because the O–D bond is harder to break.", "difficulty": "very-hard", "source": "JEE Main"},
  {"id":"chem-s-block-hydrogen-74","question":"In how many of the following reactions does H₂O₂ act as a reducing agent? (i) 2Fe²⁺ + H₂O₂ + 2H⁺ → 2Fe³⁺ + 2H₂O; (ii) 2MnO₄⁻ + 5H₂O₂ + 6H⁺ → 2Mn²⁺ + 5O₂ + 8H₂O; (iii) Mn²⁺ + H₂O₂ + 2OH⁻ → MnO₂ + 2H₂O; (iv) I₂ + H₂O₂ + 2OH⁻ → 2I⁻ + 2H₂O + O₂; (v) Cl₂ + H₂O₂ → 2HCl + O₂; (vi) 2[Fe(CN)₆]³⁻ + H₂O₂ + 2OH⁻ → 2[Fe(CN)₆]⁴⁻ + 2H₂O + O₂.","options":["2","3","5","4"],"answer":3,"explanation":"Whenever O₂ is evolved, the oxygen of H₂O₂ is oxidised (−1 → 0), so H₂O₂ is the reductant: (ii), (iv), (v), (vi) = 4. In (i) and (iii) its oxygen goes to −2 in water, so it is the oxidant. Note that (iv) is the opposite of the acid reaction, where H₂O₂ oxidises I⁻ to I₂.","difficulty":"very-hard","source":"JEE Main"},
  {"id": "chem-s-block-hydrogen-75", "question": "NaOH is added slowly to a 0.012 M solution of Mg²⁺. If Ksp of Mg(OH)₂ is 1.2 × 10⁻¹¹, Mg(OH)₂ begins to precipitate at a pH of about:", "options": ["9.5", "4.5", "10.0", "9.0"], "answer": 0, "explanation": "[OH⁻]² = Ksp/[Mg²⁺] = 1.2 × 10⁻¹¹/0.012 = 1.0 × 10⁻⁹, so [OH⁻] = 3.16 × 10⁻⁵ M, pOH = 4.5 and pH = 14 − 4.5 = 9.5. Reporting the pOH (4.5) as the pH, or forgetting the square root, are the usual slips.", "difficulty": "very-hard", "source": "JEE Main"},
  {"id": "chem-s-block-hydrogen-76", "question": "1.20 g of magnesium ribbon burns completely in air, forming 1.80 g of a mixture of MgO and Mg₃N₂. The product is then treated with excess water. The volume of NH₃ released at STP is (Mg = 24, N = 14):", "options": ["224 mL", "448 mL", "672 mL", "112 mL"], "answer": 1, "explanation": "Let x mol Mg form MgO: 40x + (0.050 − x)/3 × 100 = 1.80 gives x = 0.020, so 0.030 mol Mg forms 0.010 mol Mg₃N₂ (1.00 g; MgO 0.80 g). Mg₃N₂ + 6H₂O → 3Mg(OH)₂ + 2NH₃, so 0.020 mol NH₃ = 448 mL. Forgetting the 2 : 1 ratio gives 224 mL.", "difficulty": "very-hard", "source": "JEE Main"},
  {"id":"chem-s-block-hydrogen-77","question":"A 6.6 g mixture of NaH and CaH₂ reacts completely with water, giving 6.72 L of H₂ at STP. The mass of NaH in the mixture is (Na = 23, Ca = 40):","options":["4.2 g","3.3 g","2.4 g","1.2 g"],"answer":2,"explanation":"NaH + H₂O → NaOH + H₂ and CaH₂ + 2H₂O → Ca(OH)₂ + 2H₂. With a mol NaH and b mol CaH₂: 24a + 42b = 6.6 and a + 2b = 0.30. Solving, b = 0.10 and a = 0.10, so NaH = 2.4 g (CaH₂ = 4.2 g). Taking 1 mol H₂ per CaH₂ is the trap.","difficulty":"very-hard","source":"JEE Main"},
  {"id":"chem-s-block-hydrogen-78","question":"The overall reaction of the Solvay process (with NH₃ recovered and recycled) is 2NaCl + CaCO₃ → Na₂CO₃ + CaCl₂. The mass of pure limestone consumed per 53 kg of Na₂CO₃ produced is:","options":["100 kg","106 kg","25 kg","50 kg"],"answer":3,"explanation":"53 kg Na₂CO₃ = 0.5 kmol, and the overall equation needs 1 CaCO₃ per Na₂CO₃, so 0.5 kmol × 100 = 50 kg. Half of the CO₂ needed for carbonation comes back from calcining NaHCO₃; counting a separate CaCO₃ for each NaHCO₃ (100 kg) ignores this recycling.","difficulty":"very-hard","source":"JEE Main"},
  {"id": "chem-s-block-hydrogen-79", "question": "Assertion (A): An aqueous solution of BeCl₂ is acidic. Reason (R): The small, highly charged Be²⁺ ion strongly polarises the coordinated water in [Be(H₂O)₄]²⁺, which releases H⁺.", "options": ["Both A and R are true, and R explains A", "Both A and R are true, but R does not explain A", "A is true but R is false", "A is false but R is true"], "answer": 0, "explanation": "[Be(H₂O)₄]²⁺ ⇌ [Be(H₂O)₃(OH)]⁺ + H⁺: the very high charge density of Be²⁺ weakens the O–H bonds of bound water. This is also why BeCl₂ cannot be dehydrated simply by heating its hydrate. R correctly explains A.", "difficulty": "very-hard", "source": "JEE Main"},
  {"id": "chem-s-block-hydrogen-80", "question": "How many of the following statements are correct? (A) BeSO₄ and MgSO₄ are readily soluble in water because the high hydration enthalpies of Be²⁺ and Mg²⁺ outweigh the lattice enthalpy. (B) BeH₂ is a covalent, polymeric hydride, whereas CaH₂ is ionic. (C) Magnesium reacts vigorously with cold water, liberating H₂. (D) Strontium salts give a crimson-red flame.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "A, B and D are correct. C is wrong: magnesium reacts only very slowly with cold water (a protective Mg(OH)₂ layer forms); it reacts readily with hot water or steam.", "difficulty": "very-hard", "source": "JEE Main"},
  {"id":"chem-s-block-hydrogen-81","question":"2.7 g of aluminium and, separately, 6.5 g of zinc are each treated with excess aqueous NaOH. The total volume of H₂ evolved at STP is (Al = 27, Zn = 65):","options":["5.60 L","4.48 L","3.36 L","6.72 L"],"answer":0,"explanation":"2Al + 2NaOH + 6H₂O → 2Na[Al(OH)₄] + 3H₂: 0.10 mol Al gives 0.15 mol H₂ = 3.36 L. Zn + 2NaOH → Na₂ZnO₂ + H₂: 0.10 mol Zn gives 2.24 L. Total 5.60 L; taking 1 mol H₂ per mol Al gives 4.48 L.","difficulty":"very-hard","source":"JEE Main"},
  {"id": "chem-s-block-hydrogen-82", "question": "Match the hydrate (Column I) with the way its water is held (Column II). (a) [Cr(H₂O)₆]Cl₃, (b) BaCl₂·2H₂O, (c) CuSO₄·5H₂O. (1) Interstitial (lattice) water only, (2) All water coordinated to the metal ion, (3) Four molecules coordinated to the metal ion and one held by hydrogen bonds.", "options": ["a-1, b-2, c-3", "a-2, b-1, c-3", "a-2, b-3, c-1", "a-3, b-1, c-2"], "answer": 1, "explanation": "In [Cr(H₂O)₆]Cl₃ all six waters are ligands. In BaCl₂·2H₂O the water occupies spaces in the lattice. In CuSO₄·5H₂O four waters surround Cu²⁺ and the fifth is hydrogen-bonded between the coordinated water and the sulphate, which is why it is lost last on heating.", "difficulty": "very-hard", "source": "JEE Main"},
  {"id": "chem-s-block-hydrogen-83", "question": "How many of the following statements about the preparation of H₂O₂ are correct? (A) Electrolysis of cold 50% H₂SO₄ gives peroxodisulphate, which on hydrolysis gives H₂O₂. (B) In the 2-ethylanthraquinol auto-oxidation process the net reaction is H₂ + O₂ → H₂O₂. (C) Hydrated barium peroxide with dilute H₂SO₄ gives H₂O₂ and insoluble BaSO₄. (D) Anhydrous BaO₂ is preferred to the hydrate because it reacts faster with the acid.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "A, B and C are correct; the anthraquinol is reoxidised by air and the anthraquinone reduced back by H₂, so only H₂ and O₂ are consumed. D is wrong: anhydrous BaO₂ becomes coated with insoluble BaSO₄, which stops the reaction, so BaO₂·8H₂O is used.", "difficulty": "very-hard", "source": "JEE Main"},
  {"id": "chem-s-block-hydrogen-84", "question": "Assertion (A): Anhydrous MgCl₂, needed for electrolytic extraction of magnesium, cannot be obtained simply by heating MgCl₂·6H₂O in air. Reason (R): On heating, the hydrate undergoes hydrolysis, losing HCl and forming Mg(OH)Cl and finally MgO.", "options": ["Both A and R are true, and R explains A", "Both A and R are true, but R does not explain A", "A is true but R is false", "A is false but R is true"], "answer": 0, "explanation": "MgCl₂·6H₂O → Mg(OH)Cl + HCl + 5H₂O, and further heating gives MgO. The hydrate is therefore dehydrated in a stream of dry HCl, which suppresses the hydrolysis. R is the reason for A.", "difficulty": "very-hard", "source": "JEE Main"},
  {"id": "chem-s-block-hydrogen-85", "question": "K, Rb and Cs burn in excess oxygen to give superoxides, MO₂, whereas lithium gives only the oxide Li₂O. The best explanation is:", "options": ["Lithium has the lowest ionisation enthalpy", "Superoxides contain O²⁻ ions, which only large cations can hold", "The large O₂⁻ ion is stabilised in a lattice by large cations; the small, strongly polarising Li⁺ is matched best by the small O²⁻ ion", "Lithium reacts only with nitrogen in air"], "answer": 2, "explanation": "Lattice energy favours pairing ions of similar size: large K⁺, Rb⁺, Cs⁺ give stable lattices with the large superoxide ion, while Li⁺ would polarise and break up a peroxide or superoxide ion and is most stable with O²⁻. Superoxides contain O₂⁻, not O²⁻, and Li actually has the highest ionisation enthalpy of the group.", "difficulty": "very-hard", "source": "JEE Main"},
  {"id":"chem-s-block-hydrogen-86","question":"The chemical formula of baking soda is:","options":["NaHCO₃","Na₂CO₃","Na₂CO₃·10H₂O","NaOH"],"answer":0,"explanation":"Baking soda is sodium hydrogencarbonate, NaHCO₃. On heating it releases CO₂ (2NaHCO₃ → Na₂CO₃ + H₂O + CO₂), which makes dough rise. Na₂CO₃·10H₂O is washing soda and anhydrous Na₂CO₃ is soda ash.","difficulty":"easy","source":"JEE Main · NEET"},
  {"id":"chem-s-block-hydrogen-87","question":"Which isotope of hydrogen contains one neutron in its nucleus?","options":["None of the isotopes","Protium","Tritium","Deuterium"],"answer":3,"explanation":"Protium (¹H) has no neutron, deuterium (²H, D) has one and tritium (³H, T) has two. All three have one proton and one electron, so their chemical properties are nearly the same, though their rates of reaction differ (isotope effect).","difficulty":"easy","source":"JEE Main · NEET"},
  {"id":"chem-s-block-hydrogen-88","question":"Which of the following hydroxides is the strongest base?","options":["Ca(OH)₂","Mg(OH)₂","Ba(OH)₂","Be(OH)₂"],"answer":2,"explanation":"Down group 2 the ionic radius increases and ionisation enthalpy decreases, so the M–OH bond becomes more ionic and OH⁻ is released more easily. Ba(OH)₂ is therefore the strongest base, while Be(OH)₂ is amphoteric. Solubility of these hydroxides also increases down the group.","difficulty":"moderate","source":"JEE Main · NEET"},
  {"id":"chem-s-block-hydrogen-89","question":"Calcium hydride is called 'hydrolith' and is used as a portable source of hydrogen because:","options":["It decomposes on gentle warming into Ca and H₂","It reacts with water to liberate H₂: CaH₂ + 2H₂O → Ca(OH)₂ + 2H₂","It is a covalent hydride that sublimes","It absorbs hydrogen reversibly like palladium"],"answer":1,"explanation":"CaH₂ is an ionic (saline) hydride containing H⁻. Hydride is a strong base and reacts with water to give H₂: each mole of CaH₂ liberates 2 mol H₂. This makes it a convenient chemical store of hydrogen and a drying agent for organic solvents.","difficulty":"moderate","source":"JEE Main · NEET"},
  {"id":"chem-s-block-hydrogen-90","question":"Bleaching powder is commonly represented as:","options":["Ca(OCl)Cl","CaCl₂","Ca(ClO₃)₂","CaOCl₄"],"answer":0,"explanation":"Bleaching powder is made by passing chlorine over slaked lime: Ca(OH)₂ + Cl₂ → Ca(OCl)Cl + H₂O. Its bleaching action comes from the hypochlorite part, which releases chlorine (or HOCl) with acids. Commercial samples are a mixture, so 'available chlorine' is used to express its strength.","difficulty":"moderate","source":"JEE Main · NEET"},
  {"id":"chem-s-block-hydrogen-91","question":"Beryllium carbide (Be₂C) and aluminium carbide (Al₄C₃) both react with water to give:","options":["Ethene","Ethyne","Propyne","Methane"],"answer":3,"explanation":"Be₂C and Al₄C₃ are methanides containing isolated C⁴⁻ units, so hydrolysis gives CH₄: Be₂C + 4H₂O → 2Be(OH)₂ + CH₄. CaC₂ (C₂²⁻) gives ethyne and Mg₂C₃ (C₃⁴⁻) gives propyne. The similarity of Be and Al is an example of the diagonal relationship.","difficulty":"moderate","source":"JEE Main · NEET"},
  {"id":"chem-s-block-hydrogen-92","question":"In the water-gas shift reaction, used to increase the yield of hydrogen from synthesis gas:","options":["Coke reacts with steam: C + H₂O → CO + H₂","CH₄ reacts with steam over Ni: CH₄ + H₂O → CO + 3H₂","CO reacts with steam over an iron chromate catalyst: CO + H₂O → CO₂ + H₂","CO₂ is removed by passing through water under pressure only"],"answer":2,"explanation":"The CO in syngas is converted by steam at about 673 K over iron chromate: CO + H₂O → CO₂ + H₂, producing extra H₂. The CO₂ is then removed by scrubbing with sodium arsenite or water under pressure. Steam reforming of methane and coal gasification are the steps that produce syngas in the first place.","difficulty":"moderate","source":"JEE Main · NEET"},
  {"id":"chem-s-block-hydrogen-93","question":"Lithium is the only alkali metal that combines directly with nitrogen. When the product is treated with water:","options":["Nitrogen gas is regenerated","Ammonia is evolved: Li₃N + 3H₂O → 3LiOH + NH₃","Hydrazine is formed","Lithium nitrate and hydrogen are formed"],"answer":1,"explanation":"The small Li⁺ ion has a high charge density and gives a very high lattice enthalpy with the small, highly charged N³⁻ ion, making Li₃N stable (like Mg₃N₂, the diagonal partner). Nitride is a very strong base and is protonated by water to NH₃. Other alkali metals do not form stable nitrides by direct combination.","difficulty":"hard","source":"JEE Main"},
  {"id":"chem-s-block-hydrogen-94","question":"Dihydrogen exists as ortho and para forms. Which statement is correct?","options":["At room temperature normal H₂ is about 75% ortho (parallel nuclear spins) and 25% para; the para form has lower energy and predominates near 0 K","Ortho and para hydrogen are isotopes","Para hydrogen has parallel nuclear spins and predominates at high temperature","At room temperature the two forms are present in a 1 : 1 ratio"],"answer":0,"explanation":"The forms differ in the relative orientation of the two proton spins: ortho (parallel) and para (antiparallel). Ortho states have three spin arrangements and para one, so at high temperatures the ratio approaches 3 : 1. Para-H₂ occupies the lowest rotational level, so it becomes nearly 100% at very low temperature. The forms differ slightly in physical properties such as heat capacity.","difficulty":"hard","source":"JEE Main"},
  {"id":"chem-s-block-hydrogen-95","question":"In the solid state, beryllium hydride is:","options":["An interstitial, non-stoichiometric hydride","An ionic hydride, Be²⁺(H⁻)₂, like CaH₂","A monomeric linear BeH₂ molecule","A polymeric covalent hydride in which H atoms bridge Be atoms by three-centre two-electron bonds"],"answer":3,"explanation":"Be is too small and its ionisation enthalpy too high for an ionic lattice. Monomeric BeH₂ would leave Be with only four valence electrons, so in the solid the molecules polymerise into chains in which each H bridges two Be atoms through 3c–2e bonds (as in B₂H₆). MgH₂ is also more covalent than the hydrides of Ca, Sr and Ba.","difficulty":"hard","source":"JEE Main"},
  {"id":"chem-s-block-hydrogen-96","question":"For each molecule of ATP hydrolysed, the Na⁺/K⁺ pump (Na⁺/K⁺-ATPase) in cell membranes transports:","options":["1 Na⁺ out and 1 K⁺ in","2 Na⁺ out and 3 K⁺ in","3 Na⁺ out of the cell and 2 K⁺ into the cell","3 Na⁺ in and 2 K⁺ out"],"answer":2,"explanation":"The pump maintains high K⁺ inside and high Na⁺ outside cells by moving three Na⁺ outwards and two K⁺ inwards per ATP. Because more positive charge leaves than enters, it also contributes to the negative resting membrane potential. These gradients are essential for nerve-impulse transmission.","difficulty":"hard","source":"JEE Main"},
  {"id":"chem-s-block-hydrogen-97","question":"For good-quality Portland cement, the ratio SiO₂ : (Al₂O₃ + Fe₂O₃) should lie between 2.5 and 4, and the major oxide component (about 50–60%) is:","options":["SiO₂","CaO","Al₂O₃","MgO"],"answer":1,"explanation":"Cement clinker contains roughly 50–60% CaO, 20–25% SiO₂, 5–10% Al₂O₃ and small amounts of Fe₂O₃, MgO and SO₃. Its main compounds are dicalcium and tricalcium silicates and tricalcium aluminate. Excess lime makes cement crack on setting, while too little makes it weak; a little gypsum is added to slow setting.","difficulty":"hard","source":"JEE Main"},
  {"id":"chem-s-block-hydrogen-98","question":"Beryllium and magnesium salts do not impart any colour to the Bunsen flame, whereas Ca, Sr and Ba salts do. The reason is:","options":["Be and Mg atoms are small and their electrons are held too strongly to be excited by the energy of the flame","Be and Mg salts are not volatile at any temperature","Be and Mg emit only infrared radiation","Be and Mg salts decompose to oxides that absorb all visible light"],"answer":0,"explanation":"Flame colour requires electrons to be excited by the flame and to emit visible light as they fall back. The high ionisation and excitation energies of the small Be and Mg atoms mean the flame cannot excite them significantly. Larger Ca, Sr and Ba atoms, with more loosely held outer electrons, give brick-red, crimson and apple-green flames.","difficulty":"hard","source":"JEE Main"},
  {"id":"chem-s-block-hydrogen-99","question":"Chlorine reacts with (a) cold, dilute NaOH and (b) hot, concentrated NaOH. The chlorine-containing products are:","options":["(a) NaCl and NaClO₂; (b) NaClO₄","(a) NaCl and NaClO₃; (b) NaCl and NaOCl","(a) NaClO₄ only; (b) NaCl only","(a) NaCl and NaOCl; (b) NaCl and NaClO₃ in a 5 : 1 ratio"],"answer":3,"explanation":"Both are disproportionations of Cl₂ (0). Cold: Cl₂ + 2NaOH → NaCl + NaOCl + H₂O (−1 and +1). Hot: 3Cl₂ + 6NaOH → 5NaCl + NaClO₃ + 3H₂O, since hypochlorite itself disproportionates on heating to Cl⁻ and ClO₃⁻ (+5). Electron balance: 5 × 1 = 1 × 5.","difficulty":"hard","source":"JEE Main"},
  {"id":"chem-s-block-hydrogen-100","question":"In the Solvay process, it is NaHCO₃ rather than Na₂CO₃ that crystallises out when CO₂ is passed into ammoniacal brine. This is because:","options":["NH₃ reacts with Na₂CO₃ to give NaHCO₃","Na₂CO₃ decomposes at room temperature","NaHCO₃ is much less soluble than Na₂CO₃ and NH₄Cl in the cold brine","NaHCO₃ is less soluble because it is covalent"],"answer":2,"explanation":"In the cold, concentrated solution containing Na⁺, NH₄⁺, Cl⁻ and HCO₃⁻, NaHCO₃ is the least soluble combination, so it precipitates (NaCl + NH₄HCO₃ → NaHCO₃ + NH₄Cl). It is then filtered and calcined to Na₂CO₃. KHCO₃ is too soluble to precipitate, which is why potassium carbonate cannot be made this way.","difficulty":"hard","source":"JEE Main"},
  {"id":"chem-s-block-hydrogen-101","question":"Propene reacts with CO and H₂ in the presence of a cobalt carbonyl catalyst at high pressure (hydroformylation). The main product is:","options":["Propanal","Butanal","Butan-2-one","Propan-1-ol"],"answer":1,"explanation":"In hydroformylation (the oxo process) an H atom and a –CHO group add across the C=C bond, so the chain gains one carbon: CH₃CH=CH₂ + CO + H₂ → CH₃CH₂CH₂CHO (mainly) with some 2-methylpropanal. Reduction of the aldehyde gives butan-1-ol; this is a major industrial use of syngas (CO + H₂).","difficulty":"hard","source":"JEE Main"},
  {"id":"chem-s-block-hydrogen-102","question":"Under identical conditions, the ratio of the rates of effusion of H₂ and D₂ is:","options":["√2 : 1 (about 1.41)","2 : 1","1 : √2","4 : 1"],"answer":0,"explanation":"By Graham's law, rate ∝ 1/√M. M(H₂) = 2 and M(D₂) = 4, so r(H₂)/r(D₂) = √(4/2) = √2 ≈ 1.41. Such mass-dependent differences in diffusion and electrolysis rates are used to enrich deuterium.","difficulty":"hard","source":"JEE Main"},
  {"id":"chem-s-block-hydrogen-103","question":"Which metal liberates hydrogen when warmed with aqueous NaOH?","options":["Copper","Magnesium","Iron","Zinc"],"answer":3,"explanation":"Zinc (like Al, Sn and Be) is amphoteric and dissolves in alkali as a zincate: Zn + 2NaOH → Na₂ZnO₂ + H₂. Magnesium and iron form basic hydroxides that do not dissolve in NaOH, and copper is below hydrogen and does not react even with dilute acids.","difficulty":"hard","source":"JEE Main"},
  {"id":"chem-s-block-hydrogen-104","question":"0.74 g of Ca(OH)₂ in water is treated with 0.015 mol of CO₂. The mass of CaCO₃ remaining as a precipitate at the end is (Ca(OH)₂ = 74, CaCO₃ = 100 g mol⁻¹):","options":["0 g","1.00 g","0.50 g","0.75 g"],"answer":2,"explanation":"Ca(OH)₂ = 0.010 mol. The first 0.010 mol CO₂ precipitates 0.010 mol CaCO₃ (milkiness). The remaining 0.005 mol CO₂ dissolves CaCO₃ as soluble Ca(HCO₃)₂: CaCO₃ + CO₂ + H₂O → Ca(HCO₃)₂, leaving 0.005 mol = 0.50 g of CaCO₃ — the solution partly clears.","difficulty":"very-hard","source":"JEE Main · JEE Advanced"},
  {"id":"chem-s-block-hydrogen-105","question":"A current of 9.65 A is passed for 1000 s through brine in a membrane cell. The mass of NaOH formed and the volume of H₂ evolved at STP are:","options":["4.0 g; 2.24 L","4.0 g; 1.12 L","8.0 g; 1.12 L","2.0 g; 0.56 L"],"answer":1,"explanation":"Charge = 9.65 × 1000 = 9650 C = 0.100 F. At the cathode 2H₂O + 2e⁻ → H₂ + 2OH⁻, so 0.100 mol OH⁻ (0.100 mol NaOH = 4.0 g) and 0.050 mol H₂ (1.12 L) form. An equal 1.12 L of Cl₂ is released at the anode.","difficulty":"very-hard","source":"JEE Main · JEE Advanced"},
  {"id":"chem-s-block-hydrogen-106","question":"Gypsum, CaSO₄·2H₂O, is heated at about 393 K to convert it completely into plaster of Paris, CaSO₄·½H₂O. The percentage loss in mass is about:","options":["15.7%","20.9%","10.5%","5.2%"],"answer":0,"explanation":"M(CaSO₄·2H₂O) = 172.2 g mol⁻¹. Formation of the hemihydrate removes 1.5 H₂O = 27.0 g per mole, so the loss = 27.0/172.2 × 100 ≈ 15.7%. Losing all the water (dead burnt plaster) would give 36.0/172.2 ≈ 20.9%.","difficulty":"very-hard","source":"JEE Main · JEE Advanced"},
  {"id":"chem-s-block-hydrogen-107","question":"Given for NaCl (kJ mol⁻¹): ΔfH = −411, sublimation of Na = +108, ionisation enthalpy of Na = +496, ½ bond dissociation of Cl₂ = +121, electron gain enthalpy of Cl = −349. The lattice enthalpy (for formation of the solid from gaseous ions) is:","options":["−545 kJ mol⁻¹","−1485 kJ mol⁻¹","−89 kJ mol⁻¹","−787 kJ mol⁻¹"],"answer":3,"explanation":"By the Born–Haber cycle, ΔfH = ΔsubH + IE + ½D + ΔegH + U. So U = −411 − 108 − 496 − 121 − (−349) = −787 kJ mol⁻¹. The large lattice enthalpy outweighs the endothermic steps and makes NaCl formation strongly exothermic.","difficulty":"very-hard","source":"JEE Main · JEE Advanced"},
  {"id":"chem-s-block-hydrogen-108","question":"How many of the following statements are correct? (A) BeCl₂ exists as a chain polymer in the solid and as linear monomers in the vapour at high temperature. (B) Mg(OH)₂ is more soluble in water than Ba(OH)₂. (C) BeSO₄ is more soluble in water than BaSO₄. (D) Ca, Sr and Ba dissolve in liquid ammonia to give deep blue-black solutions. (E) MgCO₃ is thermally more stable than BaCO₃.","options":["One","Two","Three","Four"],"answer":2,"explanation":"(A) True: solid BeCl₂ has Cl bridges; above ~1200 K it is monomeric and linear. (C) True: the small Be²⁺ has a very high hydration enthalpy. (D) True: like alkali metals they give ammoniated electrons. (B) False: hydroxide solubility increases down the group. (E) False: thermal stability of carbonates increases down the group. Three correct.","difficulty":"very-hard","source":"JEE Main · JEE Advanced"},
  {"id":"chem-s-block-hydrogen-109","question":"How many of the following statements are correct? (A) Ionic hydrides react with water to liberate H₂. (B) Electrolysis of molten LiH liberates H₂ at the anode. (C) Interstitial (metallic) hydrides always have exact stoichiometric formulae. (D) NH₃ is an electron-rich hydride. (E) Atomic hydrogen produced in an electric arc is used for welding at very high temperatures.","options":["One","Two","Three","Four"],"answer":3,"explanation":"(A) True: H⁻ + H₂O → H₂ + OH⁻. (B) True: H⁻ is discharged at the anode, which proves the presence of hydride ions. (D) True: N has a lone pair beyond its bonding pairs. (E) True: recombination of H atoms releases about 436 kJ mol⁻¹, giving ~4000 °C (atomic hydrogen torch). (C) False: hydrides such as LaH₂.₈₇ and TiH₁.₅–₁.₈ are typically non-stoichiometric. Four correct.","difficulty":"very-hard","source":"JEE Main · JEE Advanced"},
  {"id":"chem-s-block-hydrogen-110","question":"Tritium decays by β⁻ emission with a half-life of 12.3 years. After 36.9 years, the fraction of a tritium sample remaining and the decay product are:","options":["1/8; ²H","1/8; ³He","1/3; ³He","1/6; ³Li"],"answer":1,"explanation":"36.9 years = 3 half-lives, so the remaining fraction is (1/2)³ = 1/8. In β⁻ decay a neutron becomes a proton: ³₁H → ³₂He + e⁻ + antineutrino, so the mass number stays 3 and the atomic number rises to 2.","difficulty":"very-hard","source":"JEE Main · JEE Advanced"},
  {"id":"chem-s-block-hydrogen-111","question":"5.0 g of bleaching powder is treated with dilute acetic acid and excess KI. The liberated iodine requires 50.0 mL of 1.0 M Na₂S₂O₃. The percentage of available chlorine is about:","options":["35.5%","71.0%","17.7%","25.0%"],"answer":0,"explanation":"Available chlorine is released by acid and oxidises iodide: Cl₂ + 2I⁻ → 2Cl⁻ + I₂, and I₂ + 2S₂O₃²⁻ → 2I⁻ + S₄O₆²⁻. So mol Cl₂ = ½ × 0.050 = 0.025 mol = 0.025 × 70.9 = 1.77 g, i.e. 35.5% of 5.0 g. Ignoring the 1 : 2 ratio gives 71%.","difficulty":"very-hard","source":"JEE Main · JEE Advanced"},
  {"id":"chem-s-block-hydrogen-112","question":"The correct decreasing order of the magnitude of hydration enthalpy is:","options":["Mg²⁺ > Be²⁺ > Na⁺ > Li⁺","Li⁺ > Be²⁺ > Mg²⁺ > Na⁺","Be²⁺ > Mg²⁺ > Li⁺ > Na⁺","Na⁺ > Li⁺ > Mg²⁺ > Be²⁺"],"answer":2,"explanation":"Hydration enthalpy grows with charge and with decreasing radius. The dipositive ions are hydrated far more strongly than the unipositive ones: Be²⁺ (≈ −2494) > Mg²⁺ (≈ −1921) ≫ Li⁺ (≈ −520) > Na⁺ (≈ −406 kJ mol⁻¹). This is why group 2 salts are usually more extensively hydrated than group 1 salts.","difficulty":"very-hard","source":"JEE Main · JEE Advanced"},
  {"id":"chem-s-block-hydrogen-113","question":"Sodium peroxide is used to regenerate air in submarines: 2Na₂O₂ + 2CO₂ → 2Na₂CO₃ + O₂. The volume of O₂ (at STP) produced by 7.8 g of Na₂O₂ is:","options":["2.24 L","1.12 L","0.56 L","4.48 L"],"answer":1,"explanation":"Na₂O₂ = 7.8/78 = 0.10 mol. Two moles of Na₂O₂ give one mole of O₂, so 0.050 mol O₂ = 0.050 × 22.4 = 1.12 L. The peroxide oxygen (−1) disproportionates: half becomes O₂ (0) and half carbonate (−2).","difficulty":"very-hard","source":"JEE Main · JEE Advanced"},
  {"id":"chem-s-block-hydrogen-114","question":"2.00 g of a mixture of CaCl₂ and NaCl is dissolved in water and treated with excess Na₂CO₃. The precipitate, after washing and drying, weighs 1.00 g. The percentage of CaCl₂ in the mixture is (CaCl₂ = 111, CaCO₃ = 100):","options":["55.5%","50.0%","44.5%","100%"],"answer":0,"explanation":"Only Ca²⁺ precipitates: CaCl₂ + Na₂CO₃ → CaCO₃ + 2NaCl. CaCO₃ = 1.00/100 = 0.0100 mol, so CaCl₂ = 0.0100 mol = 1.11 g. Percentage = 1.11/2.00 × 100 = 55.5%.","difficulty":"very-hard","source":"JEE Main · JEE Advanced"},
  {"id":"chem-s-block-hydrogen-115","question":"But-2-yne is treated with sodium in liquid ammonia at about 195 K. The product and the reason for its stereochemistry are:","options":["But-1-ene; the triple bond migrates to the end of the chain","(Z)-But-2-ene; syn addition of H₂ on the metal surface","Butane; ammoniated electrons fully reduce the triple bond","(E)-But-2-ene; the intermediate vinyl radical anion adopts the less hindered trans geometry before protonation"],"answer":3,"explanation":"Solvated electrons from Na in NH₃ add one at a time: electron addition gives a radical anion, protonation by NH₃ gives a vinyl radical, a second electron gives a vinyl anion, and a second protonation gives the alkene. The vinyl intermediates take up the more stable trans arrangement, so the trans-alkene results. Lindlar's catalyst, by contrast, gives the cis-alkene.","difficulty":"very-hard","source":"JEE Main · JEE Advanced"},
  {"id":"chem-s-block-hydrogen-116","question":"Lithium has the most negative standard reduction potential of the alkali metals, yet it reacts with water less vigorously than sodium or potassium. The best explanation is:","options":["The reaction of lithium with water is endothermic","Lithium is coated with an oxide that never dissolves in water","E° is a thermodynamic quantity; the rate is lower because Li has a high melting point and does not melt on the water, giving a smaller reacting surface, and its high ionisation enthalpy raises the activation barrier","E° values do not apply to aqueous solutions"],"answer":2,"explanation":"The very negative E°(Li⁺/Li) arises from the huge hydration enthalpy of the small Li⁺ ion, which governs the overall free-energy change, not the speed. Kinetically, lithium (m.p. 454 K) remains solid while Na and K melt from the heat of reaction and spread, exposing fresh metal. So Li reacts steadily, Na vigorously and K with ignition.","difficulty":"very-hard","source":"JEE Main · JEE Advanced"},
  {"id":"chem-s-block-hydrogen-117","question":"The pH of a 0.10 M aqueous Na₂CO₃ solution (Ka₂ of H₂CO₃ = 4.7 × 10⁻¹¹; consider only the first hydrolysis step) is about:","options":["13.00","11.66","9.83","8.34"],"answer":1,"explanation":"CO₃²⁻ + H₂O ⇌ HCO₃⁻ + OH⁻ with Kb = Kw/Ka₂ = 10⁻¹⁴/4.7 × 10⁻¹¹ = 2.13 × 10⁻⁴. [OH⁻] = √(Kb × C) = √(2.13 × 10⁻⁵) = 4.6 × 10⁻³ M, so pOH = 2.34 and pH ≈ 11.66. This strong alkalinity explains the use of washing soda as a cleaning agent.","difficulty":"very-hard","source":"JEE Main · JEE Advanced"},
  {"id":"chem-s-block-hydrogen-118","question":"Beryllium shows a maximum coordination number of 4 (as in [Be(H₂O)₄]²⁺ and [Be(OH)₄]²⁻), whereas magnesium can show 6. The reason is:","options":["Be has no d-orbitals in its valence shell, so only the 2s and three 2p orbitals (sp³) are available for bonding","Be²⁺ is larger than Mg²⁺","Be always forms ionic bonds","Be has a lower electronegativity than Mg"],"answer":0,"explanation":"Beryllium is a second-period element whose valence shell (n = 2) has just four orbitals, so it can accept at most four electron pairs, giving tetrahedral sp³ species. Its very small size also limits the number of ligands that fit around it. Magnesium, a third-period element, is larger and is not limited to an octet in the same way, so six water molecules fit around it in octahedral [Mg(H₂O)₆]²⁺.","difficulty":"very-hard","source":"JEE Main · JEE Advanced"},
];

export default questions;
